import test from 'node:test';import assert from 'node:assert/strict';import {firstVisitScript,firstVisitModes,normalizeFirstVisit,chooseFirstVisit,firstVisitGoal} from '../src/first-visit.js';import {objects} from '../src/data.js';import {zones} from '../src/zones.js';
test('approved onboarding copy keeps GSEINHQ unexpanded and all three choices available',()=>{assert.equal(zones.hq.name,'GSEINHQ');assert.deepEqual(firstVisitModes.map(m=>m.name),['Explore','Guided Adventure','Adaptive Play']);assert.equal(firstVisitScript.welcome,'Welcome, Junior Astronaut! How would you like to explore today?');assert.match(firstVisitScript.arrival,/Welcome to GSEINHQ!/);assert.match(firstVisitScript.discovery,/keep exploring/)});
test('setup is optional and changing mode preserves supports and past visits',()=>{assert.equal(normalizeFirstVisit(null).mode,'explore');assert.equal(normalizeFirstVisit({mode:'bad',movement:'joystick'}).movement,'free');const before={mode:'adaptive',movement:'destinations',extraTime:true,entered:true,interacted:true};const after=chooseFirstVisit(before,'guided');assert.equal(after.mode,'guided');assert.equal(after.movement,'destinations');assert.equal(after.extraTime,true);assert.equal(after.entered,true);assert.equal(before.mode,'adaptive');assert.deepEqual(chooseFirstVisit(before,'bad'),before)});
test('guided offers one nearest unvisited optional point and Explore offers none',()=>{const goal=firstVisitGoal('guided',objects,new Set(),zones.hq.spawn);assert.equal(goal.id,'hq-home');assert.equal(firstVisitGoal('explore',objects,new Set(),zones.hq.spawn),null);assert.equal(firstVisitGoal('adaptive',objects,new Set(),zones.hq.spawn),null);assert.notEqual(firstVisitGoal('guided',objects,new Set(['hq-home']),zones.hq.spawn).id,'hq-home');assert.equal(firstVisitGoal('guided',objects,new Set(objects.map(o=>o.id)),zones.hq.spawn).id,'hq-home')});
